// Generated ElevenLabs files are served locally; runtime audio needs no API key.
export class CitySound{
 constructor(){this.enabled=false;this.loaded=false;this.buffers=new Map();this.variants=new Map();this.loops=new Map();this.cursors=new Map();this.lastHorn=0;this.lastVoice=0;this.lastPet=0;this.volume=.55}
 async load(){if(this.loaded)return;const r=await fetch('./audio/manifest.json',{cache:'no-cache'});if(!r.ok)throw Error('Daftar audio belum tersedia.');this.manifest=await r.json();if(this.manifest.provider!=='ElevenLabs'||!this.manifest.clips?.length)throw Error('Belum ada aset audio ElevenLabs untuk diputar.');const results=await Promise.allSettled(this.manifest.clips.map(async clip=>{const r=await fetch('./audio/'+clip.file);if(!r.ok)throw Error('Audio tidak tersedia.');const buffer=await this.ctx.decodeAudioData(await r.arrayBuffer());return{buffer,...clip}}));for(const result of results){if(result.status!=='fulfilled')continue;let clip=result.value;this.buffers.set(clip.id,clip);let category=clip.category||clip.id;if(!this.variants.has(category))this.variants.set(category,[]);this.variants.get(category).push(clip)}if(!this.buffers.size)throw Error('Aset audio ElevenLabs gagal dimuat.');this.loaded=true}
 async toggle(){if(this.enabled){this.enabled=false;for(let loop of this.loops.values())try{loop.source.stop()}catch{}this.loops.clear();document.querySelector('#audio-status').textContent='Audio nonaktif';return false}if(!this.ctx)this.ctx=new(window.AudioContext||window.webkitAudioContext)();await this.ctx.resume();await this.load();this.enabled=true;document.querySelector('#audio-status').textContent='ElevenLabs · audio spasial';return true}
 pick(id){let options=this.variants.get(id)||[this.buffers.get(id)].filter(Boolean);if(!options.length)return null;let cursor=this.cursors.get(id)||0;this.cursors.set(id,cursor+1);return options[cursor%options.length]}
 play(id,{volume=.5,loop=false,x=0,z=0,positional=false}={}){if(!this.enabled)return null;let clip=this.pick(id);if(!clip)return null;let source=this.ctx.createBufferSource(),gain=this.ctx.createGain();source.buffer=clip.buffer;source.loop=loop;gain.gain.value=volume*this.volume;source.connect(gain);let panner;if(positional){panner=this.ctx.createPanner();panner.panningModel='HRTF';panner.distanceModel='inverse';panner.refDistance=6;panner.maxDistance=150;panner.rolloffFactor=1.6;panner.positionX.value=x;panner.positionY.value=1.2;panner.positionZ.value=z;gain.connect(panner).connect(this.ctx.destination)}else gain.connect(this.ctx.destination);source.start();return{source,gain,panner,clipId:clip.id}}
 loop(id,on,volume,x,z,positional=true){if(!this.enabled)return;let l=this.loops.get(id);if(!on&&l){l.source.stop();this.loops.delete(id);return}if(on&&!l){l=this.play(id,{volume,loop:true,x,z,positional});if(l)this.loops.set(id,l)}if(l){l.gain.gain.setTargetAtTime(volume*this.volume,this.ctx.currentTime,.3);if(l.panner){l.panner.positionX.value=x;l.panner.positionZ.value=z}}}
 feedback(type){this.play(type==='claim'?'pickup':type==='deliver'?'success':'pickup',{volume:.6})}
 tone(){} // Compatibility hook; all audible feedback comes from authored audio files.
 speak(text){if(!this.enabled)return;const id=/Hore|Terima kasih/.test(text)?'owner-voice':/truk/.test(text)?'rescue-voice':/Ketemu/.test(text)?'pickup':'citizen';this.play(id,{volume:.75})}
 update(t,walking,context){if(!this.enabled||!context)return;const{world,state,selfId,local,yaw}=context,l=this.ctx.listener;if(l.positionX){l.positionX.value=local.x;l.positionY.value=1.7;l.positionZ.value=local.z;l.forwardX.value=-Math.sin(yaw);l.forwardY.value=0;l.forwardZ.value=-Math.cos(yaw);l.upX.value=0;l.upY.value=1;l.upZ.value=0}this.loop('music',true,.13,0,0,false);this.loop('wind',true,.24,0,0,false);
 const trees=world.assets?.batches.find(b=>b.userData.near)?.userData.instances||[],nearest=trees.reduce((a,b)=>Math.hypot(b.x-local.x,b.z-local.z)<Math.hypot(a.x-local.x,a.z-local.z)?b:a,{x:9999,z:9999});this.loop('birds',Math.hypot(nearest.x-local.x,nearest.z-local.z)<100,.7,nearest.x,nearest.z);this.loop('river',Math.abs(local.x-world.plan.river)<110,.75,world.plan.river,local.z);
 const cars=world.assets?.carBatches?.[0]?.userData.instances||[],car=cars.reduce((a,b)=>Math.hypot(b.record.x-local.x,b.record.z-local.z)<Math.hypot(a.record.x-local.x,a.record.z-local.z)?b:a,{record:{x:9999,z:9999}}).record,carDistance=Math.hypot(car.x-local.x,car.z-local.z);this.loop('traffic',carDistance<120,.65,car.x,car.z);if(t-this.lastHorn>5&&carDistance<80){this.lastHorn=t;this.play('horn',{volume:.8,x:car.x,z:car.z,positional:true})}
 const person=world.npcs.reduce((a,b)=>Math.hypot(b.x-local.x,b.z-local.z)<Math.hypot(a.x-local.x,a.z-local.z)?b:a,{x:9999,z:9999});this.loop('crowd',Math.hypot(person.x-local.x,person.z-local.z)<65,.65,person.x,person.z);if(t-this.lastVoice>22&&Math.hypot(person.x-local.x,person.z-local.z)<15){this.lastVoice=t;this.play('citizen',{volume:.6,x:person.x,z:person.z,positional:true})}this.loop('footsteps',walking,.35,local.x,local.z,false);
 const p=state.players[selfId],working=p.releaseAt>state.now;this.loop('welding',working&&p.releaseTool==='torch',.6,state.m.truck.x,state.m.truck.z);this.loop('tools',working&&p.releaseTool!=='torch',.6,state.m.truck.x,state.m.truck.z);
 const petDistance=Math.hypot(state.pet.x-local.x,state.pet.z-local.z);if(t-this.lastPet>14&&petDistance<45&&!['captured','lost','won'].includes(state.phase)){this.lastPet=t;let group=this.manifest.clips.find(c=>(c.category||c.id).startsWith('pet-')&&c.animalIds?.includes(state.m.animal));if(group)this.play(group.category||group.id,{volume:.6,x:state.pet.x,z:state.pet.z,positional:true})}}
}
